import pandas as pd

def find_product_recommendation_pairs(product_purchases: pd.DataFrame, product_info: pd.DataFrame) -> pd.DataFrame:
    df = product_purchases.merge(product_purchases, on='user_id', suffixes=('_1', '_2'))
    df = df[df['product_id_1'] < df['product_id_2']]
    if df.empty:
        return pd.DataFrame(columns=['product1_id', 'product2_id', 'product1_category', 'product2_category', 'customer_count'])
    grouped = df.groupby(['product_id_1', 'product_id_2'])['user_id'].nunique().reset_index()
    grouped = grouped[grouped['user_id'] >= 3].rename(columns={'user_id': 'customer_count'})
    if grouped.empty:
        return pd.DataFrame(columns=['product1_id', 'product2_id', 'product1_category', 'product2_category', 'customer_count'])
    cat_map = dict(zip(product_info['product_id'], product_info['category']))
    grouped['product1_category'] = grouped['product_id_1'].map(cat_map)
    grouped['product2_category'] = grouped['product_id_2'].map(cat_map)
    grouped = grouped.rename(columns={'product_id_1': 'product1_id', 'product_id_2': 'product2_id'})
    res = grouped[['product1_id', 'product2_id', 'product1_category', 'product2_category', 'customer_count']]
    return res.sort_values(by=['customer_count', 'product1_id', 'product2_id'], ascending=[False, True, True]).reset_index(drop=True)
